package dev.gamersclt.batcaverna.nativeapp;
import android.app.Activity;import android.view.View;import android.widget.*;import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE)
public class ChatDeliveryTest {
 @Test public void sameRetryKeepsIdentityWhileChangesDoNot(){ChatSendAttempt attempt=new ChatSendAttempt();String first=attempt.begin("alice","private:bob","Olá");assertEquals(first,attempt.begin("alice","private:bob","Olá"));assertNotEquals(first,attempt.begin("alice","private:bob","Alterada"));String changed=attempt.begin("alice","private:bob","Olá");assertNotEquals(changed,attempt.begin("alice","group:bob","Olá"));String group=attempt.begin("alice","group:bob","Olá");assertNotEquals(group,attempt.begin("eve","group:bob","Olá"));attempt.clear();assertNotEquals(group,attempt.begin("alice","group:bob","Olá"));}
 @Test public void deliveryShowsRetryOnlyAfterFailure(){Activity activity=Robolectric.buildActivity(Activity.class).setup().get();int[] retried={0};ChatDeliveryStatus status=new ChatDeliveryStatus(activity,()->retried[0]++);assertEquals(View.GONE,status.getVisibility());status.sending();assertEquals(View.GONE,status.retry.getVisibility());status.failed();assertEquals(View.VISIBLE,status.retry.getVisibility());status.retry.performClick();assertEquals(1,retried[0]);status.sent();assertEquals(View.GONE,status.retry.getVisibility());activity.finish();}
 @Test public void failedNoticeAndRetryFitTogether(){Activity activity=Robolectric.buildActivity(Activity.class).setup().get();for(int screen:new int[]{320,412}){android.content.res.Configuration config=new android.content.res.Configuration(activity.getResources().getConfiguration());config.screenWidthDp=screen;android.content.Context c=activity.createConfigurationContext(config);ChatDeliveryStatus status=new ChatDeliveryStatus(c,()->{});status.failed();int width=NativeSheet.dp(c,screen-32);status.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(NativeSheet.dp(c,800),View.MeasureSpec.AT_MOST));status.layout(0,0,width,status.getMeasuredHeight());assertTrue(status.label.getWidth()>0);assertTrue(status.label.getHeight()>0);assertTrue(status.getHeight()<NativeSheet.dp(c,200));assertTrue(status.retry.getRight()<=width);}activity.finish();}

 @Test public void savedConfirmationMustBelongToTheSameContentAndRecipient()throws Exception{JSONObject expected=new JSONObject().put("id","one").put("remetente_id","alice").put("destinatario_id","bob").put("texto","Olá");JSONObject saved=new JSONObject(expected.toString()).put("created_at","now");assertTrue(AccountRepository.sameMessage(saved,expected));saved.put("destinatario_id","eve");assertFalse(AccountRepository.sameMessage(saved,expected));saved.put("destinatario_id","bob").put("texto","Outro");assertFalse(AccountRepository.sameMessage(saved,expected));}
 @Test public void readingHistoryIsNotReadingTheNewestMessage(){Activity activity=Robolectric.buildActivity(Activity.class).setup().get();ScrollView scroll=new ScrollView(activity);LinearLayout list=new LinearLayout(activity);list.setOrientation(LinearLayout.VERTICAL);scroll.addView(list);for(int i=0;i<30;i++){TextView line=new TextView(activity);line.setText("Mensagem "+i);list.addView(line,new LinearLayout.LayoutParams(-1,80));}activity.setContentView(scroll);scroll.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));scroll.layout(0,0,400,600);assertFalse(ChatReadPosition.atEnd(scroll,list));scroll.scrollTo(0,list.getHeight());assertTrue(ChatReadPosition.atEnd(scroll,list));activity.finish();}
}
